//! Error types for batch type checking.

use std::path::{Path, PathBuf};
use vize_carton::String;
use vize_carton::append;
use vize_carton::cstr;

/// Error type for Corsa-backed batch operations.
#[derive(Debug, thiserror::Error)]
pub enum CorsaError {
    /// Corsa executable not found.
    #[error("{0}")]
    CorsaNotFound(#[from] CorsaNotFoundError),

    /// IO error.
    #[error("IO error: {0}")]
    Io(#[from] std::io::Error),

    /// SFC parse error.
    #[error("SFC parse error: {0}")]
    SfcParse(String),

    /// Path error.
    #[error("Path error: {path}")]
    PathError { path: PathBuf },

    /// Corsa returned an error.
    #[error("corsa error (exit code {exit_code}): {message}")]
    CorsaExecution { exit_code: i32, message: String },

    /// JSON parse error.
    #[error("JSON parse error: {0}")]
    JsonParse(#[from] serde_json::Error),

    /// Invalid authored project configuration.
    #[error("Configuration error: {0}")]
    Configuration(String),

    /// Project not initialized.
    #[error("Virtual project not initialized. Call scan_project() first.")]
    NotInitialized,

    /// Strip prefix error.
    #[error("Failed to strip prefix from path: {0}")]
    StripPrefix(#[from] std::path::StripPrefixError),

    /// Walkdir error.
    #[error("Directory walk error: {0}")]
    WalkDir(#[from] walkdir::Error),
}

/// Result type for Corsa-backed batch operations.
pub type CorsaResult<T> = Result<T, CorsaError>;

/// Package manager type.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PackageManager {
    Pnpm,
    Npm,
    Yarn,
    Bun,
}

/// Error when a Corsa executable cannot be resolved.
#[derive(Debug)]
pub struct CorsaNotFoundError {
    detected_pm: Option<PackageManager>,
    explicit_path: Option<PathBuf>,
}

impl CorsaNotFoundError {
    /// Create a new CorsaNotFoundError.
    pub fn new(project_root: &Path) -> Self {
        let detected_pm = detect_package_manager(project_root);
        Self {
            detected_pm,
            explicit_path: None,
        }
    }

    /// Create a new CorsaNotFoundError for an explicit but missing path.
    pub fn new_explicit(project_root: &Path, path: &Path) -> Self {
        let detected_pm = detect_package_manager(project_root);
        Self {
            detected_pm,
            explicit_path: Some(path.to_path_buf()),
        }
    }

    /// Get the detected package manager.
    pub fn detected_package_manager(&self) -> Option<PackageManager> {
        self.detected_pm
    }

    /// Generate CLI error message with installation instructions.
    pub fn display_message(&self) -> String {
        let mut msg = String::default();

        msg.push_str("error: corsa not found\n\n");
        if let Some(path) = &self.explicit_path {
            append!(
                msg,
                "Configured Corsa executable does not exist: {}\n\n",
                path.display()
            );
        } else {
            msg.push_str("vize check requires 'typescript@^7' to be installed.\n\n");
        }

        if let Some(pm) = self.detected_pm {
            msg.push_str("To install, run:\n\n");
            append!(msg, "  {}\n", self.install_command(pm));
        } else {
            msg.push_str("To install, run one of the following:\n\n");
            append!(
                msg,
                "  {}  # npm\n",
                self.install_command(PackageManager::Npm)
            );
            append!(
                msg,
                "  {}  # pnpm\n",
                self.install_command(PackageManager::Pnpm)
            );
            append!(
                msg,
                "  {}  # yarn\n",
                self.install_command(PackageManager::Yarn)
            );
            append!(
                msg,
                "  {}  # bun\n",
                self.install_command(PackageManager::Bun)
            );
        }

        msg
    }

    fn install_command(&self, pm: PackageManager) -> String {
        match pm {
            PackageManager::Npm => cstr!("npm install -D typescript@^7"),
            PackageManager::Pnpm => cstr!("pnpm add -D typescript@^7"),
            PackageManager::Yarn => cstr!("yarn add -D typescript@^7"),
            PackageManager::Bun => cstr!("bun add -D typescript@^7"),
        }
    }
}

impl std::fmt::Display for CorsaNotFoundError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.display_message())
    }
}

impl std::error::Error for CorsaNotFoundError {}

/// Detect the project's package manager.
///
/// A workspace package has no lockfile of its own, so the search continues in
/// the parent directories and the nearest answer wins. It stops at the
/// repository root: a lockfile above the directory that holds `.git` belongs
/// to something else. `npm/cli/src/init/detect.ts` mirrors this search.
pub fn detect_package_manager(project_root: &Path) -> Option<PackageManager> {
    let absolute = std::path::absolute(project_root);
    let start = absolute.as_deref().unwrap_or(project_root);
    for directory in start.ancestors() {
        if let Some(detected) = detect_package_manager_in(directory) {
            return Some(detected);
        }
        if directory.join(".git").exists() {
            return None;
        }
    }
    None
}

fn detect_package_manager_in(project_root: &Path) -> Option<PackageManager> {
    // 1. Detect from lockfile (priority order)
    if project_root.join("pnpm-lock.yaml").exists() {
        return Some(PackageManager::Pnpm);
    }
    if project_root.join("bun.lockb").exists() || project_root.join("bun.lock").exists() {
        return Some(PackageManager::Bun);
    }
    if project_root.join("yarn.lock").exists() {
        return Some(PackageManager::Yarn);
    }
    if project_root.join("package-lock.json").exists() {
        return Some(PackageManager::Npm);
    }

    // 2. Detect from package.json packageManager field
    let pkg_json = project_root.join("package.json");
    if let Ok(content) = std::fs::read_to_string(&pkg_json)
        && let Ok(json) = serde_json::from_str::<serde_json::Value>(&content)
        && let Some(pm) = json.get("packageManager").and_then(|v| v.as_str())
    {
        if pm.starts_with("pnpm") {
            return Some(PackageManager::Pnpm);
        }
        if pm.starts_with("yarn") {
            return Some(PackageManager::Yarn);
        }
        if pm.starts_with("bun") {
            return Some(PackageManager::Bun);
        }
        if pm.starts_with("npm") {
            return Some(PackageManager::Npm);
        }
    }

    None
}

#[expect(
    clippy::disallowed_macros,
    reason = "insta snapshots expand to format!"
)]
#[cfg(test)]
mod tests {
    use super::{CorsaNotFoundError, PackageManager, detect_package_manager};

    #[test]
    fn workspace_package_uses_the_workspace_package_manager() {
        let workspace = tempfile::tempdir().expect("temp workspace");
        std::fs::create_dir(workspace.path().join(".git")).expect("repository root");
        std::fs::write(workspace.path().join("pnpm-lock.yaml"), "").expect("lockfile");
        let package = workspace.path().join("packages").join("app");
        std::fs::create_dir_all(&package).expect("workspace package");
        std::fs::write(package.join("package.json"), "{}").expect("package manifest");

        assert_eq!(detect_package_manager(&package), Some(PackageManager::Pnpm));

        std::fs::write(package.join("package-lock.json"), "{}").expect("nearer lockfile");
        assert_eq!(detect_package_manager(&package), Some(PackageManager::Npm));
    }

    #[test]
    fn lockfile_above_the_repository_root_is_ignored() {
        let outside = tempfile::tempdir().expect("temp directory");
        std::fs::write(outside.path().join("yarn.lock"), "").expect("unrelated lockfile");
        let repository = outside.path().join("repository");
        let package = repository.join("packages").join("app");
        std::fs::create_dir_all(&package).expect("workspace package");
        std::fs::create_dir(repository.join(".git")).expect("repository root");

        assert_eq!(detect_package_manager(&repository), None);
        assert_eq!(detect_package_manager(&package), None);
    }

    #[test]
    fn test_corsa_not_found_error_message() {
        let error = CorsaNotFoundError {
            detected_pm: Some(PackageManager::Pnpm),
            explicit_path: None,
        };

        let msg = error.display_message();
        insta::assert_snapshot!(msg.as_str());
    }

    #[test]
    fn test_corsa_not_found_no_pm() {
        let error = CorsaNotFoundError {
            detected_pm: None,
            explicit_path: None,
        };

        let msg = error.display_message();
        insta::assert_snapshot!(msg.as_str());
    }
}

base.crates/vize_canon/src/lsp_client/bootstr:
use super::{
    CorsaProjectClient,
    lifecycle_setup::{workspace_config_path, write_materialized_project_tsconfig},
    session::{ProjectSessionSpawnError, materialize_session_document, spawn_project_session},
    session_paths::build_materialized_session_document_uri,
};
use crate::file_uri::file_uri_to_path;
use std::{
    path::{Path, PathBuf},
    sync::Arc,
};
use vize_carton::corsa_resolver::{CorsaResolveError, CorsaResolveRequest};
use vize_l0::{String, cstr};

pub(super) fn resolve_corsa_executable(
    corsa_path: Option<&str>,
    working_dir: Option<&str>,
) -> Result<String, String> {
    let request = CorsaResolveRequest {
        explicit_path: corsa_path.map(Path::new),
        project_root: working_dir.map(Path::new),
    };

    match vize_carton::corsa_resolver::resolve_corsa_executable(request) {
        Ok(path) => {
            tracing::info!(executable = %path.display(), "resolved native TypeScript runtime");
            Ok(path.to_string_lossy().into())
        }
        // Preserve the historical lenient fallback: spawning a bare `corsa`
        // still lets `PATH` changes made after resolution take effect.
        Err(CorsaResolveError::NotFound) => Ok("corsa".into()),
        Err(error @ CorsaResolveError::ExplicitNotFound { .. }) => Err(cstr!("{error}")),
    }
}

impl CorsaProjectClient {
    pub(super) fn spawn_initialized_client(
        executable: &str,
        cwd: PathBuf,
        root_path: Option<PathBuf>,
        temp_dir: Option<PathBuf>,
    ) -> Result<Self, String> {
        Self::spawn_initialized_client_with_config(executable, cwd, root_path, temp_dir, None)
    }

    pub(super) fn spawn_initialized_client_with_config(
        executable: &str,
        cwd: PathBuf,
        root_path: Option<PathBuf>,
        temp_dir: Option<PathBuf>,
        config_path: Option<&Path>,
    ) -> Result<Self, String> {
        Self::spawn_initialized_client_with_transport(
            executable,
            cwd,
            root_path,
            temp_dir,
            config_path,
            false,
        )
    }

    pub(super) fn spawn_initialized_client_with_transport(
        executable: &str,
        cwd: PathBuf,
        root_path: Option<PathBuf>,
        temp_dir: Option<PathBuf>,
        config_path: Option<&Path>,
        shared_editor_transport: bool,
    ) -> Result<Self, String> {
        let project_root = root_path.as_deref().unwrap_or(&cwd);
        let explicit_project_config = config_path.map(Path::to_path_buf);
        let config_path = selected_workspace_config(project_root, config_path);
        let shared = shared_editor_transport
            .then(|| {
                super::editor_lsp::configured_project::try_shared_editor_project(
                    executable,
                    &cwd,
                    project_root,
                    &config_path,
                )
            })
            .flatten();
        let (session, capabilities, editor_lsp) =
            if let Some((session, capabilities, editor)) = shared {
                (Some(session), capabilities, Some(editor))
            } else {
                let (session, capabilities) =
                    match spawn_project_session(executable, &cwd, &config_path) {
                        Ok((session, capabilities)) => (Some(session), capabilities),
                        Err(ProjectSessionSpawnError::Unavailable(reason)) => {
                            tracing::debug!(
                                reason = reason.as_str(),
                                "using standard tsgo editor-only session"
                            );
                            (None, Arc::new(Default::default()))
                        }
                        Err(ProjectSessionSpawnError::Failed(error)) => return Err(error),
                    };
                (session, capabilities, None)
            };
        let project_session_attached_to_editor = editor_lsp.is_some();
        Ok(Self {
            executable: executable.into(),
            cwd: cwd.clone(),
            session,
            capabilities,
            overlay_api_disabled: false,
            materialized_project_session: false,
            project_root: project_root.to_path_buf(),
            explicit_project_config,
            diagnostics: Default::default(),
            overlay_versions: Default::default(),
            document_texts: Default::default(),
            session_document_uris: Default::default(),
            external_document_uris: Default::default(),
            temp_dir,
            editor_lsp,
            shared_editor_transport_requested: shared_editor_transport,
            shared_editor_transport: project_session_attached_to_editor,
            project_session_attached_to_editor,
            original_diagnosing_session: None,
            editor_lsp_documents_dirty: true,
            editor_lsp_will_rename_supported: None,
            closed: false,
        })
    }

    pub(super) fn activate_materialized_project_session(&mut self) -> Result<(), String> {
        if self.materialized_project_session {
            return Ok(());
        }

        self.retire_original_diagnosing_session()?;

        let config_path = write_materialized_project_tsconfig(&self.project_root)?;
        let documents: Vec<_> = self
            .document_texts
            .iter()
            .map(|(uri, content)| (uri.clone(), content.clone()))
            .collect();
        let mut mappings = Vec::with_capacity(documents.len());
        for (uri, content) in &documents {
            let document_uri = build_materialized_session_document_uri(uri, &self.project_root)
                .ok_or_else(|| {
                    cstr!("Failed to derive materialized Corsa overlay path for {uri}")
                })?;
            materialize_session_document(uri, document_uri.as_str(), content)
                .ok_or_else(|| cstr!("Failed to materialize Corsa overlay document for {uri}"))?;
            let path = file_uri_to_path(document_uri.as_str())
                .ok_or_else(|| cstr!("Invalid materialized Corsa document URI {document_uri}"))?;
            let written = std::fs::read_to_string(&path).map_err(|error| {
                cstr!(
                    "Failed to read materialized Corsa document {}: {error}",
                    path.display()
                )
            })?;
            if written != *content {
                return Err(cstr!(
                    "Materialized Corsa document did not preserve contents for {uri}"
                ));
            }
            mappings.push((uri.clone(), document_uri));
        }
        if self.has_project_session() {
            self.retire_project_session()?;
            let overlay_root = super::session_paths::overlay_root_for_project(&self.project_root);
            self.replace_project_transport(&config_path, &overlay_root)?;
        }
        self.session_document_uris.clear();
        self.external_document_uris.clear();
        for (uri, document_uri) in mappings {
            self.remember_session_document_uri(uri.as_str(), document_uri);
        }
        self.materialized_project_session = true;
        if self.explicit_project_config.is_some() {
            self.explicit_project_config = Some(config_path);
        }
        // An attached editor was opened against the exact new materialized
        // config above. Independent editor transports still respawn lazily.
        if self.project_session_attached_to_editor {
            Ok(())
        } else {
            self.retire_editor_lsp()
        }
    }
}

fn selected_workspace_config(root: &Path, explicit: Option<&Path>) -> PathBuf {
    explicit
        .map(Path::to_path_buf)
        .unwrap_or_else(|| workspace_config_path(root))
}

#[cfg(test)]
mod tests {
    use super::selected_workspace_config;
    use std::fs;

    #[test]
    fn explicit_generated_config_keeps_nested_authority_with_or_without_root_config() {
        let root = tempfile::tempdir().unwrap();
        let nested = root.path().join("playground/tsconfig.json");
        fs::create_dir(nested.parent().unwrap()).unwrap();
        fs::write(&nested, r#"{"compilerOptions":{"strict":true}}"#).unwrap();
        assert_eq!(
            selected_workspace_config(root.path(), Some(&nested)),
            nested
        );
        fs::write(
            root.path().join("tsconfig.json"),
            r#"{"compilerOptions":{"strict":false}}"#,
        )
        .unwrap();
        assert_eq!(
            selected_workspace_config(root.path(), Some(&nested)),
            nested
        );
    }

    #[test]
    fn omitted_config_preserves_root_tsconfig_and_jsconfig_precedence() {
        let root = tempfile::tempdir().unwrap();
        let tsconfig = root.path().join("tsconfig.json");
        let jsconfig = root.path().join("jsconfig.json");
        assert_eq!(selected_workspace_config(root.path(), None), tsconfig);
        fs::write(&jsconfig, "{}").unwrap();
        assert_eq!(selected_workspace_config(root.path(), None), jsconfig);
        fs::write(&tsconfig, "{}").unwrap();
        assert_eq!(selected_workspace_config(root.path(), None), tsconfig);
    }
}

base.crates/vize_carton/src/corsa_resolver.rs:
//! Unified Corsa/native TypeScript executable discovery.
//!
//! Historically three independent resolvers existed (canon's LSP client, canon's
//! batch executor, and patina's type-aware linter session) and they could pick
//! different binaries for the same project. This module is the single source of
//! truth they all share.
//!
//! Resolution order:
//!
//! 1. Explicit configuration ([`CorsaResolveRequest::explicit_path`]).
//! 2. Environment variables, in precedence order: `CORSA_PATH`,
//!    `CORSA_EXECUTABLE`, `TSGO_PATH`, `TSGO_EXECUTABLE`, `TSRS_PATH`,
//!    `TSRS_EXECUTABLE`. The first one set wins; its value must point at an
//!    existing file.
//! 3. Project discovery: an ancestor walk from the project root (and the
//!    current directory) probing project caches, dev-checkout paths, stable
//!    `typescript@7` platform packages, the bundled `node_modules/vize`
//!    runtime, legacy `@typescript/native-preview` layouts, pnpm store
//!    fallbacks, and finally local `node_modules/.bin` wrappers. Current native
//!    runtimes across these roots take precedence over legacy previews; each
//!    tier retains nearest-directory and start-root order.
//! 4. Common global install locations under `$HOME` plus `npm root -g`.
//! 5. A `PATH` lookup for `corsa` then `tsgo`.
//!
//! Developer-checkout paths (`ref/typescript-go/...`, `../corsa-bind`, and the
//! compile-time workspace root) are probed only in debug builds or when
//! `VIZE_CORSA_DEV_PATHS` is set to a non-empty value other than `0`, so
//! production binaries never scan repo-internal layouts.

use std::ffi::OsString;
use std::path::{Path, PathBuf};

mod packages;
use packages::{
    find_node_modules_native, find_node_modules_tsrs_native, find_node_modules_wrapper,
};

#[cfg(test)]
mod normalize_tests;

/// Environment variables honored by the resolver, in precedence order.
pub const CORSA_ENV_VARS: [&str; 6] = [
    "CORSA_PATH",
    "CORSA_EXECUTABLE",
    "TSGO_PATH",
    "TSGO_EXECUTABLE",
    "TSRS_PATH",
    "TSRS_EXECUTABLE",
];

/// Executable names probed by every discovery source, in precedence order.
pub const CORSA_EXECUTABLE_NAMES: [&str; 3] = ["corsa", "tsgo", "tsrs"];

/// Environment variable gating developer-checkout discovery paths.
pub const CORSA_DEV_PATHS_ENV: &str = "VIZE_CORSA_DEV_PATHS";

/// Input for [`resolve_corsa_executable`].
#[derive(Debug, Clone, Copy, Default)]
pub struct CorsaResolveRequest<'a> {
    /// Explicitly configured executable path (CLI flag or config file).
    /// Takes precedence over everything else and must exist.
    pub explicit_path: Option<&'a Path>,
    /// Project root used to anchor relative explicit/env paths and the
    /// discovery ancestor walk.
    pub project_root: Option<&'a Path>,
}

/// Failure modes of [`resolve_corsa_executable`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CorsaResolveError {
    /// An explicitly requested path (config or environment variable) does not
    /// exist on disk.
    ExplicitNotFound {
        /// Where the path came from: `"configuration"` or an env var name.
        source: &'static str,
        /// The (relative-resolved) path that was probed.
        path: PathBuf,
    },
    /// No executable was found by any discovery source.
    NotFound,
}

impl std::fmt::Display for CorsaResolveError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::ExplicitNotFound { source, path } => write!(
                f,
                "Configured Corsa executable does not exist: {} (from {source})",
                path.display()
            ),
            Self::NotFound => write!(f, "No Corsa executable found"),
        }
    }
}

impl std::error::Error for CorsaResolveError {}

/// Resolve the Corsa executable for a project.
///
/// See the module docs for the full resolution order.
pub fn resolve_corsa_executable(
    request: CorsaResolveRequest<'_>,
) -> Result<PathBuf, CorsaResolveError> {
    resolve_with_env(request, |name| std::env::var_os(name))
}

/// Discover a Corsa executable by walking `start` and its ancestors, without
/// consulting env vars, `$HOME`, `npm root -g`, or `PATH`.
///
/// This is the discovery subset used to normalize wrapper paths; it is also
/// useful for tests that need a project-scoped lookup.
pub fn discover_corsa_in_ancestors(start: &Path) -> Option<PathBuf> {
    discover_in_walk(&[start.to_path_buf()], dev_paths_enabled())
}

/// Re-resolve a `node_modules/.bin` wrapper path to the native binary it
/// shadows, when one can be discovered from the wrapper's project root.
/// Non-wrapper paths are returned unchanged.
pub fn normalize_corsa_path(path: &Path) -> PathBuf {
    normalize_corsa_path_with_discovery(path, |project_root| {
        if path.file_name().is_some_and(|name| name == "tsrs")
            && let Some(native) = find_node_modules_tsrs_native(project_root)
        {
            return Some(native);
        }
        discover_in_walk(&[project_root.to_path_buf()], dev_paths_enabled())
    })
}

fn normalize_corsa_path_with_discovery(
    path: &Path,
    discover: impl FnOnce(&Path) -> Option<PathBuf>,
) -> PathBuf {
    let Some(project_root) = wrapper_project_root(path) else {
        return path.to_path_buf();
    };
    match discover(project_root) {
        Some(resolved) if resolved != path => resolved,
        _ => path.to_path_buf(),
    }
}

/// The `@typescript/*-*` platform suffix for the current target.
pub fn platform_suffix() -> &'static str {
    if cfg!(target_os = "macos") {
        if cfg!(target_arch = "aarch64") {
            "darwin-arm64"
        } else {
            "darwin-x64"
        }
    } else if cfg!(target_os = "linux") {
        if cfg!(target_arch = "aarch64") {
            "linux-arm64"
        } else {
            "linux-x64"
        }
    } else if cfg!(target_os = "windows") {
        if cfg!(target_arch = "aarch64") {
            "win32-arm64"
        } else {
            "win32-x64"
        }
    } else {
        ""
    }
}

fn resolve_with_env(
    request: CorsaResolveRequest<'_>,
    env: impl Fn(&str) -> Option<OsString>,
) -> Result<PathBuf, CorsaResolveError> {
    if let Some(path) = request.explicit_path {
        return resolve_required_path(path, "configuration", request.project_root);
    }

    for env_var in CORSA_ENV_VARS {
        let Some(value) = env(env_var) else {
            continue;
        };
        if value.is_empty() {
            continue;
        }
        return resolve_required_path(Path::new(&value), env_var, request.project_root);
    }

    discover_runtime(request.project_root).ok_or(CorsaResolveError::NotFound)
}

/// Resolve an explicitly requested path: anchor relative paths, require
/// existence, normalize wrappers, and canonicalize.
fn resolve_required_path(
    path: &Path,
    source: &'static str,
    project_root: Option<&Path>,
) -> Result<PathBuf, CorsaResolveError> {
    let resolved = resolve_relative_path(path, project_root);
    if !resolved.exists() {
        return Err(CorsaResolveError::ExplicitNotFound {
            source,
            path: resolved,
        });
    }
    let normalized = normalize_corsa_path(&resolved);
    Ok(normalized.canonicalize().unwrap_or(normalized))
}

fn resolve_relative_path(path: &Path, project_root: Option<&Path>) -> PathBuf {
    if path.is_absolute() {
        return path.to_path_buf();
    }

    let project_candidate = project_root.map(|root| root.join(path));
    if let Some(candidate) = &project_candidate
        && candidate.exists()
    {
        return candidate.clone();
    }

    if let Ok(cwd) = std::env::current_dir() {
        let cwd_candidate = cwd.join(path);
        if cwd_candidate.exists() {
            return cwd_candidate;
        }
    }

    project_candidate.unwrap_or_else(|| path.to_path_buf())
}

fn discover_runtime(project_root: Option<&Path>) -> Option<PathBuf> {
    let dev_paths = dev_paths_enabled();
    let mut walk_starts = Vec::new();
    if let Some(root) = project_root {
        push_unique(&mut walk_starts, root.to_path_buf());
    }
    if let Ok(cwd) = std::env::current_dir() {
        push_unique(&mut walk_starts, cwd);
    }
    if dev_paths && let Some(workspace_root) = compile_time_workspace_root() {
        push_unique(&mut walk_starts, workspace_root);
    }

    if let Some(found) = discover_in_walk(&walk_starts, dev_paths) {
        return Some(found);
    }
    if let Some(found) = find_in_home_locations() {
        return Some(found);
    }
    if let Some(found) = find_in_npm_global_root() {
        return Some(found);
    }
    find_in_path_lookup().map(|path| normalize_corsa_path(&path))
}

/// Whether developer-checkout paths may be probed.
fn dev_paths_enabled() -> bool {
    match std::env::var_os(CORSA_DEV_PATHS_ENV) {
        Some(value) => !value.is_empty() && value != "0",
        None => cfg!(debug_assertions),
    }
}

/// The vize workspace root captured at compile time. Only meaningful for
/// binaries running on a machine with the vize checkout (i.e. development).
fn compile_time_workspace_root() -> Option<PathBuf> {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .map(Path::to_path_buf)
}

enum Candidate {
    Native(PathBuf),
    Legacy(PathBuf),
    Wrapper(PathBuf),
}

/// Walk every start directory and its ancestors, preferring a native binary
/// found anywhere over legacy preview runtimes, then over local wrappers.
/// An older project preview may lack the API supported by Vize's runtime;
/// retain it only when no current runtime is installed in the discovery roots.
fn discover_in_walk(walk_starts: &[PathBuf], dev_paths: bool) -> Option<PathBuf> {
    let mut legacy_fallback: Option<PathBuf> = None;
    let mut wrapper_fallback: Option<PathBuf> = None;
    let mut visited: Vec<&Path> = Vec::new();

    for start in walk_starts {
        for dir in start.ancestors() {
            if visited.contains(&dir) {
                continue;
            }
            visited.push(dir);
            match probe_directory(dir, dev_paths) {
                Some(Candidate::Native(path)) => return Some(path),
                Some(Candidate::Legacy(path)) => {
                    legacy_fallback.get_or_insert(path);
                }
                Some(Candidate::Wrapper(path)) => {
                    wrapper_fallback.get_or_insert(path);
                }
                None => {}
            }
        }
    }

    legacy_fallback.or(wrapper_fallback)
}

fn probe_directory(dir: &Path, dev_paths: bool) -> Option<Candidate> {
    if let Some(path) = find_project_cache(dir, dev_paths) {
        return Some(Candidate::Native(path));
    }
    if dev_paths
        && let Some(parent) = dir.parent()
        && let Some(path) = find_project_cache(&parent.join("corsa-bind"), dev_paths)
    {
        return Some(Candidate::Native(path));
    }
    if let Some(path) = find_node_modules_native(dir) {
        return Some(path);
    }
    find_node_modules_wrapper(dir).map(Candidate::Wrapper)
}

fn find_project_cache(dir: &Path, dev_paths: bool) -> Option<PathBuf> {
    let mut cache_dirs = vec![dir.join(".cache")];
    if dev_paths {
        let typescript_go = dir.join("ref").join("typescript-go");
        cache_dirs.push(typescript_go.join(".cache"));
        cache_dirs.push(typescript_go.join("built").join("local"));
    }

    for cache_dir in cache_dirs {
        for executable in CORSA_EXECUTABLE_NAMES {
            if let Some(found) = existing_executable(&cache_dir, executable) {
                return Some(found);
            }
        }
    }

    None
}

/// Probe `dir/{name}` and `dir/{name}.exe`. npm's Windows platform packages
/// ship `lib/tsgo.exe`; every other platform ships an extensionless binary.
fn existing_executable(dir: &Path, executable: &str) -> Option<PathBuf> {
    let plain = dir.join(executable);
    if plain.exists() {
        return Some(plain);
    }
    let windows = dir.join(&*crate::cstr!("{executable}.exe"));
    if windows.exists() {
        return Some(windows);
    }
    None
}

fn find_in_home_locations() -> Option<PathBuf> {
    const HOME_RELATIVE: [&str; 7] = [
        ".npm-global/bin",
        ".npm/bin",
        ".local/share/pnpm",
        ".volta/bin",
        ".asdf/shims",
        ".local/share/fnm/node-versions/current/bin",
        ".nvm/versions/node/current/bin",
    ];
    const SYSTEM_BIN_DIRS: [&str; 2] = ["/opt/homebrew/bin", "/usr/local/bin"];

    let home = std::env::var_os("HOME").map(PathBuf::from)?;
    for executable in CORSA_EXECUTABLE_NAMES {
        for prefix in HOME_RELATIVE {
            let candidate = home.join(prefix).join(executable);
            if candidate.exists() {
                return Some(candidate);
            }
        }
        for system_dir in SYSTEM_BIN_DIRS {
            let candidate = Path::new(system_dir).join(executable);
            if candidate.exists() {
                return Some(candidate);
            }
        }
    }

    None
}

fn find_in_npm_global_root() -> Option<PathBuf> {
    let output = std::process::Command::new("npm")
        .args(["root", "-g"])
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }

    let npm_root = String::from_utf8_lossy(&output.stdout);
    let bin_dir = Path::new(npm_root.trim()).parent()?.join("bin");
    for executable in CORSA_EXECUTABLE_NAMES {
        let candidate = bin_dir.join(executable);
        if candidate.exists() {
            return Some(candidate);
        }
    }

    None
}

fn find_in_path_lookup() -> Option<PathBuf> {
    for executable in CORSA_EXECUTABLE_NAMES {
        if let Ok(path) = which::which(executable) {
            return Some(path);
        }
    }

    None
}

fn wrapper_project_root(path: &Path) -> Option<&Path> {
    let bin_dir = path.parent()?;
    if bin_dir.file_name()? != ".bin" {
        return None;
    }
    let node_modules = bin_dir.parent()?;
    if node_modules.file_name()? != "node_modules" {
        return None;
    }
    node_modules.parent()
}

fn push_unique(paths: &mut Vec<PathBuf>, candidate: PathBuf) {
    if !paths.contains(&candidate) {
        paths.push(candidate);
    }
}

