}

#[cfg(test)]
pub(crate) fn lint_sfc_with_corsa(linter: &Linter, source: &str, filename: &str) -> LintResult {
    let descriptor = profile!(
        "patina.type_aware.parse_sfc",
        super::script_rules::parse_sfc_for_lint(source, filename)
    )
    .ok();

    lint_sfc_with_corsa_descriptor(linter, source, filename, descriptor.as_ref(), false)
}

pub(crate) fn lint_sfc_with_corsa_descriptor<'a>(
    linter: &Linter,
    source: &'a str,
    filename: &str,
    descriptor: Option<&'a SfcDescriptor<'a>>,
    derived: bool,
) -> LintResult {
    let mut result = match descriptor {
        Some(descriptor) => profile!(
            "patina.type_aware.driver",
            driver::lint_with_descriptor(linter, source, filename, descriptor, derived)
        ),
        None => {
            if let Some((content, byte_offset)) = super::engine::extract_template_fast(source) {
                let mut fallback = profile!(
                    "patina.type_aware.fallback_template_lint",
                    linter.lint_template(&content, filename)
                );
                if byte_offset > 0 {
                    for diag in &mut fallback.diagnostics {
                        diag.start += byte_offset;
                        diag.end += byte_offset;
                        for label in &mut diag.labels {
                            label.start += byte_offset;
                            label.end += byte_offset;
                        }
                    }
                }
                fallback
            } else {
                LintResult {
                    filename: filename.to_compact_string(),
                    diagnostics: Vec::new(),
                    error_count: 0,
                    warning_count: 0,
                }
            }
        }
    };

    super::severity::apply_severity_overrides(&mut result, &linter.severity_overrides);
    result.filename = filename.to_compact_string();
    result
}

pub(super) fn push_warning(result: &mut LintResult, diagnostic: LintDiagnostic) {
    result.warning_count += 1;
    result.diagnostics.push(diagnostic);
}

/// Push a warning whose ranges are in croquis' script-analysis frame, moved
/// into the file through [`ScriptFrame`](crate::output::frame::ScriptFrame)
/// (FP-1). A range the frame cannot locate is not reported; a debug build
/// treats it as a caller bug.
pub(super) fn push_script_warning(
    result: &mut LintResult,
    descriptor: &vize_atelier_sfc::SfcDescriptor<'_>,
    diagnostic: LintDiagnostic,
) {
    let reframed = crate::output::frame::ScriptFrame::for_lint(descriptor)
        .and_then(|frame| frame.reframe(&diagnostic));
    match reframed {
        Some(reframed) => push_warning(result, reframed),
        None => debug_assert!(
            false,
            "{}: a script-analysis range needs an SFC script block that contains it",
            diagnostic.rule_name
        ),
    }
}

pub(super) fn with_corsa_session<T>(
    linter: &Linter,
    filename: &str,
    f: impl FnOnce(&mut CorsaTypeAwareSession) -> Result<T, String>,
) -> Result<T, TypeAwareFailure> {
    let project_root = super::corsa_session::resolve_project_root(filename);
    let tsconfig = {
        let mut ownership = linter.type_aware_project_ownership.lock().map_err(|_| {
            TypeAwareFailure::Runtime(
                "Failed to lock type-aware project ownership".to_compact_string(),
            )
        })?;
        super::corsa_session::effective_tsconfig_for_source(
            filename,
            linter.type_aware_tsconfig.as_deref(),
            &mut ownership,
        )
    };
    if let Some(tsconfig) = tsconfig.as_ref() {
        let configuration_error = {
            let mut configs = linter.type_aware_project_configs.lock().map_err(|_| {
                TypeAwareFailure::Runtime(
                    "Failed to lock type-aware project configurations".to_compact_string(),
                )
            })?;
            configs
                .entry(tsconfig.clone())
                .or_insert_with(|| {
                    super::corsa_session::validate_tsconfig(&project_root, tsconfig).err()
                })
                .clone()
        };
        if let Some(message) = configuration_error {
            let report = linter
                .reported_type_aware_project_configs
                .lock()
                .map_err(|_| {
                    TypeAwareFailure::Runtime(
                        "Failed to lock reported type-aware project configurations"
                            .to_compact_string(),
                    )
                })?
                .insert(tsconfig.clone());
            return Err(TypeAwareFailure::ProjectConfiguration { message, report });
        }
    }

    let key = CorsaSessionKey {
        project_root,
        tsconfig: tsconfig.clone(),
    };
    let corsa_path = linter.corsa_path.clone();
    let spawn_tsconfig = tsconfig.clone();
    linter
        .native_corsa
        .with_session(
            key,
            || {
                profile!(
                    "patina.type_aware.corsa.new_session",
                    CorsaTypeAwareSession::new_with_corsa_path(
                        filename,
                        corsa_path.as_deref(),
                        spawn_tsconfig,
                    )
                )
            },
            |session| {
                debug_assert!(session.matches_source_file(filename, tsconfig.as_deref()));
                profile!("patina.type_aware.corsa.session_work", f(session))
            },
        )
        .map_err(TypeAwareFailure::Runtime)
}

pub(super) fn push_type_aware_failure(result: &mut LintResult, failure: TypeAwareFailure) {
    match failure {
        TypeAwareFailure::ProjectConfiguration {
            message,
            report: true,
        } => {
            result.error_count += 1;
            result.diagnostics.push(
                LintDiagnostic::error("type/project-configuration", message, 0, 0).with_help(
                    "Generate or repair the referenced TypeScript configuration before running type-aware lint.",
                ),
            );
        }
        TypeAwareFailure::ProjectConfiguration { report: false, .. } => {}
        TypeAwareFailure::Runtime(error) => push_warning(
            result,
            LintDiagnostic::warn("type/corsa-runtime", error, 0, 0).with_help(
                "Type-aware lint rules were skipped because the native compiler could not be started. Install a native TypeScript runtime in this project or configure `typeChecker.corsaPath`, `CORSA_PATH`, or `TSGO_PATH` to its executable.",
            ),
        ),
    }
}

pub(super) fn should_warn_for_prop_access(probe: Option<&TypeProbe>) -> bool {
    let Some(probe) = probe else {
        return true;
    };
    if probe.type_texts.is_empty() {
        return true;
    }
    is_any_like_type_texts(&probe.type_texts) || is_unknown_like_type_texts(&probe.type_texts)
}

pub(super) fn should_warn_for_emit_validator(probe: Option<&TypeProbe>) -> bool {
    let Some(probe) = probe else {
        return true;
    };
    if probe.call_signatures.is_empty() {
        return true;
    }
    probe.call_signatures.iter().any(|signature| {
        signature.iter().any(|parameter_type| {
            parameter_type.is_empty()
                || is_any_like_type_texts(parameter_type)
                || is_unknown_like_type_texts(parameter_type)
        })
    })
}

pub(super) fn has_promise_like_return(probe: &TypeProbe) -> bool {
    let no_properties: &[vize_l0::CompactString] = &[];
    probe.return_types.iter().any(|return_type| {
        !return_type.is_empty() && is_promise_like_type_texts(return_type, no_properties)
    })
}

pub(super) fn has_unsafe_template_type(probe: Option<&TypeProbe>) -> bool {
    let Some(probe) = probe else {
        return false;
    };
    !probe.type_texts.is_empty()
        && (is_any_like_type_texts(&probe.type_texts)
            || is_unknown_like_type_texts(&probe.type_texts))
}

pub(super) fn should_warn_for_reactivity_loss(probe: Option<&TypeProbe>) -> bool {
    let Some(probe) = probe else {
        return true;
    };
    if probe.type_texts.is_empty() {
        return true;
    }
    if is_any_like_type_texts(&probe.type_texts) || is_unknown_like_type_texts(&probe.type_texts) {
        return true;
    }
    !has_reactive_wrapper_type(probe)
}

fn has_reactive_wrapper_type(probe: &TypeProbe) -> bool {
    probe
        .type_texts
        .iter()
        .any(|text| is_reactive_wrapper_type_text(text.as_str()))
}

fn is_reactive_wrapper_type_text(text: &str) -> bool {
    text.contains("Ref<")
        || text.contains("Ref <")
        || text.contains("ComputedRef<")
        || text.contains("ComputedRef <")
        || text.contains("WritableComputedRef<")
        || text.contains("WritableComputedRef <")
        || text.contains("ShallowRef<")
        || text.contains("ShallowRef <")
        || text.contains("ModelRef<")
        || text.contains("ModelRef <")
}

//! Complete public JSX/TSX packets; the source replay appends this test only.
use super::{JsxLang, LintPreset, LintResult, Linter};
use serde_json::{Value, json};
use std::path::PathBuf;

const RULES: [&str; 2] = ["type/no-floating-promises", "type/no-reactivity-loss"];

fn complete(result: &LintResult) -> Value {
    let diagnostics: Vec<_> = result.diagnostics.iter().map(|d| {
        let labels: Vec<_> = d.labels.iter().map(|l| json!({"message":l.message.as_str(),"start":l.start,"end":l.end})).collect();
        json!({"rule_name":d.rule_name,"severity":d.severity,"message":d.message.as_str(),"start":d.start,"end":d.end,"help":d.help.as_ref().map(|help|help.as_str()),"labels":labels,"fix":d.fix})
    }).collect();
    json!({"filename":result.filename.as_str(),"error_count":result.error_count,"warning_count":result.warning_count,"diagnostics":diagnostics})
}

fn warning(rule: &str, message: &str, help: &str, start: usize, end: usize) -> Value {
    json!({"rule_name":rule,"severity":"warning","message":message,"start":start,"end":end,"help":help,"labels":[],"fix":null})
}

fn capture(version: &Value, packets: &[Value]) {
    if let Some(directory) = std::env::var_os("VIZE_PLAIN_TYPE_PACKETS_CAPTURE_DIR") {
        let directory = PathBuf::from(directory);
        std::fs::create_dir_all(&directory).unwrap();
        std::fs::write(
            directory.join("packets.json"),
            serde_json::to_vec_pretty(&json!({"provider_version":version,"packets":packets}))
                .unwrap(),
        )
        .unwrap();
    }
}

#[test]
fn conditional_plain_type_packets_are_complete() {
    let required = std::env::var("VIZE_PLAIN_TYPE_PACKETS_REQUIRED").as_deref() == Ok("1");
    if std::env::var("VIZE_TEST_DISABLE_TSGO").as_deref() == Ok("1") {
        assert!(
            !required,
            "required native packets cannot run with the checker disabled"
        );
        return;
    }
    let runtime = std::env::var_os("VIZE_PLAIN_TYPE_PACKETS_CORSA_PATH")
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            PathBuf::from(env!("CARGO_MANIFEST_DIR"))
                .join("../../node_modules/@typescript")
                .join(format!(
                    "typescript-{}",
                    vize_carton::corsa_resolver::platform_suffix()
                ))
                .join("lib")
                .join(format!("tsc{}", std::env::consts::EXE_SUFFIX))
        });
    if !runtime.is_file() {
        assert!(!required, "required native packet provider is missing");
        return;
    }
    let package: Value = serde_json::from_slice(
        &std::fs::read(
            runtime
                .parent()
                .unwrap()
                .parent()
                .unwrap()
                .join("package.json"),
        )
        .unwrap(),
    )
    .unwrap();
    assert_eq!(
        package["version"], "7.0.2",
        "packet authority must be the pinned provider"
    );
    let temporary = tempfile::tempdir().unwrap();
    let root = std::env::var_os("VIZE_PLAIN_TYPE_PACKETS_CASE_ROOT")
        .map(PathBuf::from)
        .unwrap_or_else(|| temporary.path().to_owned());
    std::fs::create_dir_all(&root).unwrap();
    std::fs::write(root.join("package.json"), "{\"type\":\"module\"}\n").unwrap();
    std::fs::write(root.join("tsconfig.json"), "{\"compilerOptions\":{\"strict\":true,\"target\":\"ESNext\",\"module\":\"ESNext\",\"moduleResolution\":\"Bundler\",\"jsx\":\"preserve\"},\"include\":[\"*.tsx\"]}\n").unwrap();
    let missing = root.join("missing-provider");
    assert!(!missing.exists());
    let inputs = std::env::var_os("VIZE_PLAIN_TYPE_PACKETS_INPUT_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            PathBuf::from(env!("CARGO_MANIFEST_DIR"))
                .join("../../tests/_fixtures/differential/linter/conditional-plain-types-10517")
        });
    let mut packets = Vec::new();
    for kind in ["promise", "reactivity"] {
        for (case, extension) in [
            ("active", "tsx"),
            ("javascript", "jsx"),
            ("declaration-ts", "d.ts"),
            ("declaration-mts", "d.mts"),
            ("declaration-cts", "d.cts"),
            ("default", "tsx"),
            ("host-disabled", "tsx"),
            ("rule-disabled", "tsx"),
            ("unavailable", "tsx"),
            ("no-query", "tsx"),
        ] {
            let filename = root.join(format!("{kind}-{case}.{extension}"));
            let filename = filename.to_str().unwrap();
            let input = match case {
                "no-query" => "no-query.tsx.txt".to_owned(),
                "default" => format!("{kind}-default.tsx.txt"),
                _ => format!("{kind}.{extension}.txt"),
            };
            let current = std::fs::read_to_string(inputs.join(&input)).unwrap();
            std::fs::write(filename, &current).unwrap();
            let selected = if case == "unavailable" || case == "no-query" {
                &missing
            } else {
                &runtime
            };
            let mut linter = Linter::with_preset(LintPreset::Opinionated)
                .with_corsa_path(Some(selected.clone()));
            if case != "default" {
                linter = linter
                    .with_enabled_rules(Some(RULES.iter().map(|rule| (*rule).into()).collect()));
            }
            if case == "host-disabled" {
                linter = linter.with_type_aware_lint(false);
            }
            if case == "rule-disabled" {
                linter =
                    linter.with_disabled_rules(RULES.iter().map(|rule| (*rule).into()).collect());
            }
            let result = linter.lint_jsx(
                &current,
                filename,
                if extension == "jsx" {
                    JsxLang::Jsx
                } else {
                    JsxLang::Tsx
                },
            );
            let diagnostics = if case == "active" {
                if kind == "promise" {
                    let start = current.find("save();").unwrap();
                    vec![warning(
                        "type/no-floating-promises",
                        "Floating Promise must be awaited, returned, or explicitly ignored with `void`",
                        "Add `await`, return the Promise, or prefix it with `void` when the fire-and-forget behavior is intentional.",
                        start,
                        start + 6,
                    )]
                } else {
                    let start = current.find("state.count").unwrap();
                    vec![warning(
                        "type/no-reactivity-loss",
                        "Assigning 'state.count' to 'count' stores a plain snapshot",
                        "Use `toRef(source, 'key')`, `toRefs(source)`, or access the property on the reactive object.",
                        start,
                        start + 11,
                    )]
                }
            } else if case == "unavailable" {
                vec![warning(
                    "type/corsa-runtime",
                    &format!(
                        "Configured Corsa executable does not exist: {} (from configuration)",
                        missing.display()
                    ),
                    "Type-aware lint rules were skipped because the native compiler could not be started. Install a native TypeScript runtime in this project or configure `typeChecker.corsaPath`, `CORSA_PATH`, or `TSGO_PATH` to its executable.",
                    0,
                    0,
                )]
            } else {
                Vec::new()
            };
            let expected = json!({"filename":filename,"error_count":0,"warning_count":diagnostics.len(),"diagnostics":diagnostics});
            let actual = complete(&result);
            packets.push(json!({"kind":kind,"case":case,"source":current,"expected":expected,"actual":actual}));
            capture(&package["version"], &packets);
            assert_eq!(actual, expected, "{kind}/{case} complete public packet");
            Linter::finish_type_aware_lint(std::slice::from_ref(&linter), &[]);
        }
    }
}

