    let package = binary
        .parent()
        .unwrap()
        .parent()
        .unwrap()
        .join("package.json");
    fs::write(
        package,
        &*crate::cstr!(
            r#"{{"name":"@typescript/typescript-{}","version":"7.0.2"}}"#,
            platform_suffix()
        ),
    )
    .unwrap();
    assert_eq!(discover_in_walk(&[root.to_path_buf()], false), None);
}

